mapper.select:
select dcod.id AS id, dco.flow_name as cfgOutputName, CASE WHEN dco.exec_system = 'restCloud' THEN dco.flow_name ELSE dcic.type END AS name, dco.exec_url as execUrl, dco.exec_system as execSystem, dbs.id AS systemId, dbs.code AS systemCode, dbs.name AS systemName, dcod.main_id AS mainId, dcod.next_level_id AS nextLevelId, dcod.next_level_type AS nextLevelType, dcod.last_time AS lastTime, dcod.next_time AS nextTime, dcod.interval_time AS intervalTime, dcod.override_time AS overrideTime, dcod.max_retry_count AS maxRetryCount, dcod.exec_timeout AS execTimeout, dcod.disabled AS disabled, dcod.extend_json AS extendJson, dcod.create_time AS createTime, dcod.update_time AS updateTime, dcod.create_user_name AS createUserName, dcod.create_user_id AS createUserId, dcod.update_user_name AS updateUserName, dcod.update_user_id AS updateUserId, dcod.version AS version, dcod.is_deleted AS isDeleted, dcod.remark AS remark, dcod.dealy_time AS dealyTime from dmp_cfg_output_detail dcod left join dmp_cfg_output dco on dcod.main_id = dco.id left join dmp_basic_system dbs on dco.system_id = dbs.id left join dmp_cfg_input_convert dcic on dco.input_convert_id = dcic.id where ${params.sqlMap.default} and dcod.is_deleted = false
and dcod.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
dcod.create_time DESC

SELECT dcod.disabled AS tabFlag, CASE WHEN dcod.disabled = FALSE THEN '启用' ELSE '停用' END AS tabFlagName, count(*) AS count FROM dmp_cfg_output_detail dcod WHERE dcod.is_deleted=FALSE
${params.permissionSql}
GROUP BY dcod.disabled
